import"./chunk-2NFLSA4Y.js";var o={atom:{theory:{concept:"[[An atom is the smallest particle of a chemical element that still has the properties of that element.]] It has a tiny, heavy nucleus in the centre, made of protons (positive) and neutrons (no charge), and light, negative electrons around it. [[The number of protons decides which element the atom is: 1 proton is always hydrogen, 6 is always carbon.]] An atom with as many electrons as protons is neutral; with fewer or more electrons it becomes an ion. Atoms of one element with different numbers of neutrons are called isotopes."},section:{proton:{title:"Proton  p\u207A",text:"Charge +1, mass \u2248 1 u. Lives in the nucleus. The number of protons Z (atomic number) gives the element its name and place in the periodic table."},neutron:{title:"Neutron  n",text:"No charge, mass \u2248 1 u. Lives in the nucleus and helps hold it together. Changing the neutrons does not change the element."},electron:{title:"Electron  e\u207B",text:"Charge \u22121, mass about 1/1836 of a proton \u2014 almost nothing. Electrons are around the nucleus and decide how the atom reacts with other atoms."},ion:{title:"Ions",text:"[[An atom that lost electrons becomes a positive ion (for example Na\u207A); one that gained electrons becomes a negative ion (for example Cl\u207B).]] The nucleus does not change."},isotope:{title:"Isotopes",text:"[[Atoms of the same element with different numbers of neutrons: carbon-12 and carbon-14 are both carbon.]] Some isotopes are stable, others are radioactive and slowly change into other atoms."},shells:{title:"Electron shells",text:"Electrons fill shells from the inside out: 2 in the first, 8 in the second, 8 in the third (school rule for the first 20 elements). Electrons in the outermost shell are valence electrons."},quantum:{title:"The quantum picture",text:"[[Electrons do not really travel on paths like planets.]] Quantum mechanics only tells us where an electron is likely to be \u2014 an \u201Celectron cloud\u201D. Switch the picture to compare both models."}},formula:{massNumber:"Mass number",charge:"Charge of the atom",shellCapacity:"Most electrons in shell n (the school rule fills only 8 in the third shell first)",radius:"Approximate radius of the nucleus",hydrogen:"Energy levels of the hydrogen atom"},variable:{elementaryCharge:"Elementary charge (1.6 \xB7 10\u207B\xB9\u2079 C)"},assumption:{bohr:"The moving-electron picture is the simplified Bohr model; real electrons are described by probability clouds.",scale:"Not to scale: a real atom is about 100 000 times larger than its nucleus.",shells:"Shells are filled with the school rule 2-8-8, which works for the first 20 elements.",mass:"The atomic mass ignores the binding energy of the nucleus, so it is slightly too large (under 1 %).",nucleons:"Protons and neutrons are drawn as balls; they are actually made of smaller particles called quarks."},param:{protons:"Protons",neutrons:"Neutrons",electrons:"Electrons",picture:"Model"},hint:{protons:"The number of protons decides the element.",neutrons:"Change the neutrons to make a different isotope.",electrons:"Fewer or more electrons than protons make an ion.",picture:"Bohr model: paths. Electron cloud: where electrons are likely to be."},picture:{bohr:"Bohr model (shells)",cloud:"Electron cloud (quantum)"},measure:{protons:"Protons (atomic number)",neutrons:"Neutrons",electrons:"Electrons",shells:"Electron shells",valence:"Valence electrons",atomicMass:"Atomic mass",nuclearRadius:"Nucleus radius",massNumber:"Mass number",charge:"Charge"},view:{neutral:"neutral atom",ion:"ion {charge}",stable:"stable",radioactive:"radioactive",bohrModel:"Bohr model (simplified, not to scale)",cloudModel:"Electron cloud \u2014 quantum model (not to scale)"},element:{"1":"Hydrogen","2":"Helium","3":"Lithium","4":"Beryllium","5":"Boron","6":"Carbon","7":"Nitrogen","8":"Oxygen","9":"Fluorine","10":"Neon","11":"Sodium","12":"Magnesium","13":"Aluminium","14":"Silicon","15":"Phosphorus","16":"Sulfur","17":"Chlorine","18":"Argon","19":"Potassium","20":"Calcium"},challenge:{carbon12:{title:"Build carbon-12",description:"Build a neutral carbon-12 atom \u2014 the atom all living things are built on.",hint:"Carbon has 6 protons. Mass number 12 = protons + neutrons."},oxygen:{title:"The air we breathe",description:"Build a neutral, stable oxygen atom.",hint:"Oxygen is element 8. Stable oxygen has 8, 9 or 10 neutrons."},sodium:{title:"Salt ion",description:"Build the sodium ion Na\u207A found in table salt (sodium-23).",hint:"Na\u207A has lost one electron: 11 protons, 12 neutrons, 10 electrons."},deuterium:{title:"Heavy hydrogen",description:"Build deuterium: a neutral hydrogen atom with one neutron.",hint:"Hydrogen has 1 proton. Deuterium adds one neutron."},carbon14:{title:"Radioactive clock",description:"Build a neutral carbon-14 atom, used to find the age of old bones and wood.",hint:"Still carbon (6 protons), but A = 14."},fullShell:{title:"Like a noble gas",description:"Make an ion of a stable, non-noble element whose outer shell is full (2, 10 or 18 electrons).",hint:"Na\u207A (11 protons, 10 electrons) or Cl\u207B (17 protons, 18 electrons) both work."}}}},n={sim:o};export{n as default,o as sim};
